package uk.ac.ravensbourne.casevault.crypto;
import static org.junit.jupiter.api.Assertions.*; import java.nio.charset.StandardCharsets; import org.junit.jupiter.api.Test;
class TinkKeysetProviderTest { @Test void tCrypto001MissingProductionKeysetRefusesStartup(){assertThrows(IllegalStateException.class,()->new TinkKeysetConfiguration().fileKeysetProvider(""));} @Test void tCrypto002DifferentRunKeysetCannotDecryptCiphertext() throws Exception {var first=new TinkKeysetConfiguration().testKeysetProvider();var second=new TinkKeysetConfiguration().testKeysetProvider();byte[] aad="case:file".getBytes(StandardCharsets.UTF_8);byte[] cipher=first.aead().encrypt("synthetic".getBytes(StandardCharsets.UTF_8),aad);assertThrows(Exception.class,()->second.aead().decrypt(cipher,aad));} }
